mapper.select:
SELECT 
FROM kb_eval_runs
WHERE id = #{id}
  AND user_id = #{userId}

SELECT 
FROM kb_eval_runs
WHERE user_id = #{userId}
  AND kb_id = #{kbId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}

mapper.delete:
DELETE FROM kb_eval_runs
WHERE user_id = #{userId}
  AND kb_id = #{kbId}
  AND id NOT IN (
      SELECT id FROM (
          SELECT id
          FROM kb_eval_runs
          WHERE user_id = #{userId}
            AND kb_id = #{kbId}
          ORDER BY created_at DESC, id DESC
          LIMIT #{keep}
      ) keep
  )
